from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .source_api_association_config import SourceApiAssociationConfig, SourceApiAssociationConfigDict


class V1SourceApisMergedApiAssociationsRequest(SdkBaseModel):
    merged_api_identifier: str = Field(alias="mergedApiIdentifier")
    """The identifier of the AppSync Merged API. This is generated by the AppSync service. In most cases, Merged APIs
    (especially in your account) only require the API ID value or ARN of the merged API. However, Merged APIs in other
    accounts (cross-account use cases) strictly require the full resource ARN of the merged API."""

    description: Optional[str] = UNSET
    """The description field."""

    source_api_association_config: Optional[SourceApiAssociationConfig] = Field(
        default=UNSET, alias="sourceApiAssociationConfig"
    )


class V1SourceApisMergedApiAssociationsRequestDict(TypedDict):
    merged_api_identifier: str
    description: NotRequired[str]
    source_api_association_config: NotRequired[SourceApiAssociationConfigDict]
